    // demand_6(0).
    v44 := true;
    f45 := false;
    for k46 in [0..next_demand_6_h.length) {
      if next_demand_6_1[k46] == 0 { next_demand_6_h[k46] = next_demand_6_h[k46] || v44; f45 = true; }
    }
    if !f45 { next_demand_6_1 = next_demand_6_1 ~ [0]; next_demand_6_h = next_demand_6_h ~ [v44]; }
    demand_4_1 = next_demand_4_1;
    demand_4_2 = next_demand_4_2;
    demand_4_h = next_demand_4_h;
    demand_6_1 = next_demand_6_1;
    demand_6_h = next_demand_6_h;
    step_1 = next_step_1;
    step_2 = next_step_2;
    step_3 = next_step_3;
    step_h = next_step_h;
    stage7 = stage7 + 1;
  }

  demand_5_1 := []: ℤ[];
  demand_5_h := []: 𝔹[];
  // demand_5(V) :- demand_6(Min), at(I,V), V >= Min, D is V - Min, step(I,0,D), I1 is I + 1.
  for k47 in [0..demand_6_h.length) {
    Min := demand_6_1[k47];
    x48 := demand_6_h[k47];
    for k49 in [0..at_h.length) {
      I := at_1[k49];
      V := at_2[k49];
      x50 := at_h[k49];
