  v56 := true;
  f57 := false;
  for k58 in [0..demand_5_h.length) {
    if demand_5_1[k58] == 0 { demand_5_h[k58] = demand_5_h[k58] || v56; f57 = true; }
  }
  if !f57 { demand_5_1 = demand_5_1 ~ [0]; demand_5_h = demand_5_h ~ [v56]; }

  elements_1 := elements_facts_1;
  elements_h := elements_facts_h;

  ends_1 := []: ℤ[];
  ends_h := []: 𝔹[];
  // 0.5::ends(I) :- elements(N), between(0,N,I).
  for k59 in [0..elements_h.length) {
