  list_1 := []: ℤ[];
  list_2 := []: ℤ[];
  list_h := []: 𝔹[];
  stage65 := 0;
  before66 := -1;
  while stage65 < list_h.length || list_h.length != before66 {
    before66 = list_h.length;
    next_list_1 := []: ℤ[];
    next_list_2 := []: ℤ[];
    next_list_h := []: 𝔹[];
    // list(N,Anon1) :- demand_5(Anon1), elements(N), ends(N).
    for k67 in [0..demand_5_h.length) {
      Anon1 := demand_5_1[k67];
      x68 := demand_5_h[k67];
      for k69 in [0..elements_h.length) {
        N := elements_1[k69];
        x70 := elements_h[k69];
        for k71 in [0..ends_h.length) {
          if ends_1[k71] == N {
            x72 := ends_h[k71];
            v73 := x68 && x70 && x72;
            f74 := false;
            for k75 in [0..next_list_h.length) {
              if next_list_1[k75] == N && next_list_2[k75] == Anon1 { next_list_h[k75] = next_list_h[k75] || v73; f74 = true; }
            }
            if !f74 { next_list_1 = next_list_1 ~ [N]; next_list_2 = next_list_2 ~ [Anon1]; next_list_h = next_list_h ~ [v73]; }
          }
        }
      }
    }
    // list(I,Min) :- demand_6(Min), at(I,V), \+ ends(I), V >= Min, D is V - Min, step(I,0,D), I1 is I + 1, list(I1,V).
    for k76 in [0..demand_6_h.length) {
      Min := demand_6_1[k76];
      x77 := demand_6_h[k76];
      for k78 in [0..at_h.length) {
        I := at_1[k78];
        V := at_2[k78];
        x79 := at_h[k78];
        n80 := false;
        for k81 in [0..ends_h.length) { if ends_1[k81] == I { n80 = n80 || ends_h[k81]; } }
        if V >= Min {
          D := (V - Min);
          I1 := (I + 1);
          for k82 in [0..step_h.length) {
            if step_1[k82] == I && step_2[k82] == 0 && step_3[k82] == D {
              x83 := step_h[k82];
              for k84 in [0..list_h.length) {
                if list_1[k84] == I1 && list_2[k84] == V {
                  x85 := list_h[k84];
                  v86 := x77 && x79 && !n80 && x83 && x85;
                  f87 := false;
                  for k88 in [0..next_list_h.length) {
                    if next_list_1[k88] == I && next_list_2[k88] == Min { next_list_h[k88] = next_list_h[k88] || v86; f87 = true; }
                  }
                  if !f87 { next_list_1 = next_list_1 ~ [I]; next_list_2 = next_list_2 ~ [Min]; next_list_h = next_list_h ~ [v86]; }
                }
              }
            }
          }
        }
      }
    }
    list_1 = next_list_1;
    list_2 = next_list_2;
    list_h = next_list_h;
    stage65 = stage65 + 1;
  }

  generated_h := []: 𝔹[];
  // generated :- list(0,0).
  for k89 in [0..list_h.length) {
    if list_1[k89] == 0 && list_2[k89] == 0 {
      x90 := list_h[k89];
      v91 := x90;
      f92 := false;
      for k93 in [0..generated_h.length) {
        if true { generated_h[k93] = generated_h[k93] || v91; f92 = true; }
      }
      if !f92 { generated_h = generated_h ~ [v91]; }
    }
  }

  q94 := false;
  for q94_k in [0..generated_h.length) { if true { q94 = generated_h[q94_k]; } }
  queries := [q94];
  return queries[0];
}

