// a coin of probability p, drawn once in a world
var coin = function(p) { return mem(function() { return flip(p); }); };
var and = function(xs) { return function() { return all(function(x) { return x(); }, xs); }; };
var not = function(x) { return function() { return !x(); }; };
var keyOf = function(t) { return JSON.stringify(t); };
// whether the tuple t of r holds
var holds = function(r, t) { var e = r[keyOf(t)]; return e ? e.v : no; };
// the entry of t, if it is a tuple of r: none or one to map over
var probe = function(r, t) { var e = r[keyOf(t)]; return e ? [e] : []; };
// the entries of r by their values at positions ps (from 0)
var index = function(r, ps) {
  return _.groupBy(map(function(e) { return {k: keyOf(_.at(e.t, ps)), t: e.t, v: e.v}; }, _.values(r)), 'k');
};
// whether a tuple of the index's key k holds
var holdsAny = function(ix, k) {
  var es = ix[keyOf(k)] || [];
  return function() { return any(function(e) { return e.v(); }, es); };
};
// the choice of an annotated disjunction p1::h1; ...; pn::hn: whether each
// head is the one chosen, the k-th with probability pk and none with the rest
var choose = function(ps) {
  var rest = 1 - sum(ps);
  var vs = _.range(ps.length + (rest > 0 ? 1 : 0));
  var c = mem(function() { return categorical({ps: rest > 0 ? ps.concat([rest]) : ps, vs: vs}); });
  return map(function(k) { return function() { return c() === k; }; }, _.range(ps.length));
};
// the instances, [relation, tuple, holding] each, of relation `name`
var only = function(name, instances) { return filter(function(i) { return i[0] === name; }, instances); };
// the relation of base and instances: a tuple holds where its fact or one
// of its instances does
var relation = function(base, instances) {
  var entries = map(function(e) { return {k: keyOf(e.t), t: e.t, v: e.v}; }, _.values(base)).concat(
    map(function(i) { return {k: keyOf(i[1]), t: i[1], v: i[2]}; }, instances));
  return mapObject(function(k, es) {
    var vs = map(function(e) { return e.v; }, es);
    return {t: es[0].t, v: mem(function() { return any(function(x) { return x(); }, vs); })};
  }, _.groupBy(entries, 'k'));
};
// a relation of facts, [argument ..., probability] each
var relationOfFacts = function(rows) {
  return _.fromPairs(map(function(row) {
    var t = row.slice(0, row.length - 1), p = row[row.length - 1];
    return [keyOf(t), {t: t, v: p >= 1 ? yes : coin(p)}];
  }, rows));
};

var w_facts = relationOfFacts(lpFacts['w/2'] || []);
var symbols_facts = relationOfFacts(lpFacts['symbols/1'] || []);

var w = w_facts;

var instances_s_order = [].concat(
  // 0.5::s_order(I) :- w(I,_A1).
  (function() {
    return _.flatten(map(function(e1) {
      var I = e1.t[0];
      var _A1 = e1.t[1];
      return [['s_order', [I], and([e1.v, coin(0.5)])]];
    }, _.values(w)));
  })()
);
var s_order = relation({}, instances_s_order);

var instances_x_ends = [].concat(
  // 0.5::x_ends(I) :- w(I,_A1).
  (function() {
    return _.flatten(map(function(e1) {
      var I = e1.t[0];
      var _A1 = e1.t[1];
      return [['x_ends', [I], and([e1.v, coin(0.5)])]];
    }, _.values(w)));
  })()
);
var x_ends = relation({}, instances_x_ends);

var w_by_2 = index(w, [1]);
// x/2: recursive; the rules applied in stages from no tuple, each
// reading the stage before, until a stage adds no tuple and the stages number the tuples
var stage_x = function(rels) {
  var x = rels[0];
  var x_by_1 = index(x, [0]);
  var instances_x = [].concat(
    // x(I,J) :- w(I,a), x_ends(I), J is I + 1.
    (function() {
      return _.flatten(map(function(e1) {
        var I = e1.t[0];
        var J = (I + 1);
        return _.flatten(map(function(e2) {
          return [['x', [I, J], and([e1.v, e2.v])]];
        }, probe(x_ends, [I])));
      }, (w_by_2[keyOf(['a'])] || [])));
    })(),
    // x(I,J) :- w(I,b), \+ x_ends(I), I1 is I + 1, x(I1,K), x(K,J).
    (function() {
      return _.flatten(map(function(e1) {
        var I = e1.t[0];
        var I1 = (I + 1);
        return _.flatten(map(function(e2) {
          var K = e2.t[1];
          return _.flatten(map(function(e3) {
            var J = e3.t[1];
            return [['x', [I, J], and([e1.v, not(holds(x_ends, [I])), e2.v, e3.v])]];
          }, (x_by_1[keyOf([K])] || [])));
        }, (x_by_1[keyOf([I1])] || [])));
      }, (w_by_2[keyOf(['b'])] || [])));
    })()
  );
  var next_x = relation({}, instances_x);
  return [next_x];
};
var stages_x = function(rels, stage, before) {
  var size = sum(map(function(r) { return _.size(r); }, rels));
  return stage < size || size !== before ? stages_x(stage_x(rels), stage + 1, size) : rels;
};
var rels_x = stages_x([{}], 0, -1);
var x = rels_x[0];

var instances_y_ends = [].concat(
  // 0.5::y_ends(I) :- w(I,_A1).
  (function() {
    return _.flatten(map(function(e1) {
      var I = e1.t[0];
      var _A1 = e1.t[1];
      return [['y_ends', [I], and([e1.v, coin(0.5)])]];
    }, _.values(w)));
  })()
);
var y_ends = relation({}, instances_y_ends);

var instances_y_xx = [].concat(
  // 0.5::y_xx(I) :- w(I,_A1).
  (function() {
    return _.flatten(map(function(e1) {
      var I = e1.t[0];
      var _A1 = e1.t[1];
      return [['y_xx', [I], and([e1.v, coin(0.5)])]];
    }, _.values(w)));
  })()
);
var y_xx = relation({}, instances_y_xx);

var x_by_1 = index(x, [0]);
// s/2, y/2: recursive; the rules applied in stages from no tuple, each
// reading the stage before, until a stage adds no tuple and the stages number the tuples
var stage_s = function(rels) {
  var s = rels[0];
  var y = rels[1];
  var s_by_1 = index(s, [0]);
  var y_by_1 = index(y, [0]);
  var instances_s = [].concat(
    // y(I,J) :- w(I,c), y_ends(I), J is I + 1.
    (function() {
      return _.flatten(map(function(e1) {
        var I = e1.t[0];
        var J = (I + 1);
        return _.flatten(map(function(e2) {
          return [['y', [I, J], and([e1.v, e2.v])]];
        }, probe(y_ends, [I])));
      }, (w_by_2[keyOf(['c'])] || [])));
    })(),
    // y(I,J) :- w(I,c), \+ y_ends(I), y_xx(I), I1 is I + 1, x(I1,J).
    (function() {
      return _.flatten(map(function(e1) {
        var I = e1.t[0];
        var I1 = (I + 1);
        return _.flatten(map(function(e2) {
          return _.flatten(map(function(e3) {
            var J = e3.t[1];
            return [['y', [I, J], and([e1.v, not(holds(y_ends, [I])), e2.v, e3.v])]];
          }, (x_by_1[keyOf([I1])] || [])));
        }, probe(y_xx, [I])));
      }, (w_by_2[keyOf(['c'])] || [])));
    })(),
    // y(I,J) :- w(I,c), \+ y_ends(I), \+ y_xx(I), I1 is I + 1, s(I1,J).
    (function() {
      return _.flatten(map(function(e1) {
        var I = e1.t[0];
        var I1 = (I + 1);
        return _.flatten(map(function(e2) {
          var J = e2.t[1];
          return [['y', [I, J], and([e1.v, not(holds(y_ends, [I])), not(holds(y_xx, [I])), e2.v])]];
        }, (s_by_1[keyOf([I1])] || [])));
      }, (w_by_2[keyOf(['c'])] || [])));
    })(),
    // s(I,J) :- s_order(I), x(I,K), y(K,J).
    (function() {
      return _.flatten(map(function(e1) {
        var I = e1.t[0];
        return _.flatten(map(function(e2) {
          var K = e2.t[1];
          return _.flatten(map(function(e3) {
            var J = e3.t[1];
            return [['s', [I, J], and([e1.v, e2.v, e3.v])]];
          }, (y_by_1[keyOf([K])] || [])));
        }, (x_by_1[keyOf([I])] || [])));
      }, _.values(s_order)));
    })(),
    // s(I,J) :- \+ s_order(I), y(I,K), x(K,J).
    (function() {
      return _.flatten(map(function(e1) {
        var I = e1.t[0];
        var K = e1.t[1];
        return _.flatten(map(function(e2) {
          var J = e2.t[1];
          return [['s', [I, J], and([e1.v, not(holds(s_order, [I])), e2.v])]];
        }, (x_by_1[keyOf([K])] || [])));
      }, _.values(y)));
    })()
  );
  var next_s = relation({}, only('s', instances_s));
  var next_y = relation({}, only('y', instances_s));
  return [next_s, next_y];
};
var stages_s = function(rels, stage, before) {
  var size = sum(map(function(r) { return _.size(r); }, rels));
  return stage < size || size !== before ? stages_s(stage_s(rels), stage + 1, size) : rels;
};
var rels_s = stages_s([{}, {}], 0, -1);
var s = rels_s[0];
var y = rels_s[1];

var symbols = symbols_facts;

var instances_generated = [].concat(
  // generated :- symbols(N), s(0,N).
  (function() {
    return _.flatten(map(function(e1) {
      var N = e1.t[0];
      return _.flatten(map(function(e2) {
        return [['generated', [], and([e1.v, e2.v])]];
      }, probe(s, [0, N])));
    }, _.values(symbols)));
  })()
);
var generated = relation({}, instances_generated);

// component 0 bool
var model = function() {
  return [holds(generated, [])()];
};
Infer({method: 'enumerate'}, model);

